{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

THERAPY_CATALOG_PATH = ROOT / 'therapy_catalog.json'
BAG_SUPPLY_COST_PATH = ROOT / 'bag_supply_cost.csv'
DELIVERY_PAYMENT_PATH = ROOT / 'delivery_payment.csv'
PATIENT_OVERRIDES_PATH = ROOT / 'patient_overrides.csv'
ANALYSIS_OUTPUT_PATH = ROOT / 'infusion_batch_analysis.json'
SUMMARY_OUTPUT_PATH = ROOT / 'infusion_batch_summary.md'

ASSUMPTIONS = {
    'deliveries_per_year_7_day': 52,
    'deliveries_per_year_14_day': 26,
    'days_per_delivery_7_day': 7,
    'days_per_delivery_14_day': 14,
    'switch_threshold_usd': 15000,
    'patient_override_rule': 'highest approved revision per therapy_code',
}


def money(value):
    return round(float(value) + 1e-9, 2)


def load_csv(path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def alias_keys(label):
    label = str(label).strip()
    return [label, label.lower()]


def main():
    with THERAPY_CATALOG_PATH.open() as f:
        catalog = json.load(f)

    in_scope = []
    for service_line in catalog.get('service_lines', []):
        for therapy in service_line.get('therapies', []):
            if therapy.get('include_in_review') is True:
                in_scope.append(therapy)

    therapy_by_code = {therapy['therapy_code']: therapy for therapy in in_scope}

    alias_to_code = {}
    for therapy in in_scope:
        code = therapy['therapy_code']
        labels = [therapy.get('therapy_name', '')] + list(therapy.get('aliases') or [])
        for label in labels:
            if label:
                for key in alias_keys(label):
                    alias_to_code[key] = code

    payment_by_code = {}
    for row in load_csv(DELIVERY_PAYMENT_PATH):
        label = row.get('therapy_label', '')
        code = None
        for key in alias_keys(label):
            code = alias_to_code.get(key)
            if code:
                break
        if code in therapy_by_code:
            payment_by_code[code] = float(row['payment_per_delivery_per_patient_usd'])

    approved_override_by_code = {}
    override_rows = load_csv(PATIENT_OVERRIDES_PATH)
    if override_rows:
        patient_col_candidates = [
            'active_patients',
            'patient_count',
            'patients',
            'active_patient_count',
        ]
        patient_col = next((c for c in patient_col_candidates if c in override_rows[0]), None)
        if patient_col is None:
            raise KeyError(f'Could not find patient count column in {PATIENT_OVERRIDES_PATH}')
    else:
        patient_col = 'active_patients'

    for row in override_rows:
        code = row.get('therapy_code', '').strip()
        if row.get('status', '').strip() != 'approved' or code not in therapy_by_code:
            continue
        revision = int(row['revision'])
        current = approved_override_by_code.get(code)
        if current is None or revision > current['revision']:
            approved_override_by_code[code] = {
                'revision': revision,
                'active_patients': int(row[patient_col]),
            }

    bag_supply_cost_by_size = {}
    for row in load_csv(BAG_SUPPLY_COST_PATH):
        bag_supply_cost_by_size[int(row['bag_size_ml'])] = float(row['bag_supply_cost_usd'])

    therapies_output = []
    for code in sorted(therapy_by_code):
        therapy = therapy_by_code[code]
        if code not in approved_override_by_code:
            raise KeyError(f'Missing approved patient override for in-scope therapy_code {code}')
        if code not in payment_by_code:
            raise KeyError(f'Missing delivery payment for in-scope therapy_code {code}')

        active_patients = approved_override_by_code[code]['active_patients']
        selected_revision = approved_override_by_code[code]['revision']
        drug_cost_per_1000 = float(therapy['drug_cost_per_1000_mg_usd'])
        dose_mg_per_day = float(therapy['dose_mg_per_day'])
        bag_size_ml = int(therapy['bag_size_ml'])
        bag_supply_cost = bag_supply_cost_by_size[bag_size_ml]
        payment = payment_by_code[code]

        def compute_model(days_per_delivery, deliveries_per_year):
            annual_drug_cost = (
                drug_cost_per_1000
                * active_patients
                * dose_mg_per_day
                * days_per_delivery
                * deliveries_per_year
                / 1000
            )
            annual_supply_cost = bag_supply_cost * active_patients * deliveries_per_year
            annual_revenue = payment * active_patients * deliveries_per_year
            annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
            return {
                'drug_cost': money(annual_drug_cost),
                'supply_cost': money(annual_supply_cost),
                'revenue': money(annual_revenue),
                'margin': money(annual_margin),
            }

        model_7 = compute_model(
            ASSUMPTIONS['days_per_delivery_7_day'],
            ASSUMPTIONS['deliveries_per_year_7_day'],
        )
        model_14 = compute_model(
            ASSUMPTIONS['days_per_delivery_14_day'],
            ASSUMPTIONS['deliveries_per_year_14_day'],
        )

        therapies_output.append({
            'therapy_code': code,
            'therapy_name': therapy['therapy_name'],
            'active_patients': active_patients,
            'selected_patient_override_revision': selected_revision,
            'dose_mg_per_day': money(dose_mg_per_day),
            'drug_cost_per_1000_mg_usd': money(drug_cost_per_1000),
            'bag_size_ml': bag_size_ml,
            'bag_supply_cost_usd': money(bag_supply_cost),
            'payment_per_delivery_per_patient_usd': money(payment),
            'annual_drug_cost_7_day_usd': model_7['drug_cost'],
            'annual_supply_cost_7_day_usd': model_7['supply_cost'],
            'annual_revenue_7_day_usd': model_7['revenue'],
            'annual_margin_7_day_usd': model_7['margin'],
            'annual_drug_cost_14_day_usd': model_14['drug_cost'],
            'annual_supply_cost_14_day_usd': model_14['supply_cost'],
            'annual_revenue_14_day_usd': model_14['revenue'],
            'annual_margin_14_day_usd': model_14['margin'],
            'annual_margin_difference_14_minus_7_usd': money(model_14['margin'] - model_7['margin']),
        })

    total_7 = money(sum(t['annual_margin_7_day_usd'] for t in therapies_output))
    total_14 = money(sum(t['annual_margin_14_day_usd'] for t in therapies_output))
    total_diff = money(total_14 - total_7)
    abs_total_diff = money(abs(total_diff))
    decision = 'move_to_14_day' if abs_total_diff < ASSUMPTIONS['switch_threshold_usd'] else 'keep_7_day'

    if decision == 'move_to_14_day':
        justification = (
            f"Absolute annual margin difference is ${abs_total_diff:,.2f}, below the "
            f"${ASSUMPTIONS['switch_threshold_usd']:,.2f} threshold."
        )
    else:
        justification = (
            f"Absolute annual margin difference is ${abs_total_diff:,.2f}, at or above the "
            f"${ASSUMPTIONS['switch_threshold_usd']:,.2f} threshold."
        )

    analysis = {
        'assumptions': ASSUMPTIONS,
        'therapies': therapies_output,
        'totals': {
            'total_annual_margin_7_day_usd': total_7,
            'total_annual_margin_14_day_usd': total_14,
            'total_annual_margin_difference_14_minus_7_usd': total_diff,
            'absolute_total_margin_difference_usd': abs_total_diff,
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    with ANALYSIS_OUTPUT_PATH.open('w') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    summary_lines = [
        'Infusion Batch Analysis Summary',
        f"Total 7-day margin (USD): ${total_7:,.2f}",
        f"Total 14-day margin (USD): ${total_14:,.2f}",
        f"Absolute difference (USD): ${abs_total_diff:,.2f}",
        f"Decision: {decision}",
    ]
    SUMMARY_OUTPUT_PATH.write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
